1	// Pin the GPA-to-file-offset contract for hybrid shared mode: a narrow RAM
2	// region [base, base+size) over an mmap span translates GPA `base + N` to
3	// file offset `N`, so QEMU and vsim see identical bytes through the same
4	// backing file. Also guards against SimpleMemory's size-check rejecting an
5	// external buffer sized to match a sub-2.25 GB region.
6	
7	#include "platform/mmap_backing.hpp"
8	#include "platform/simple_memory.hpp"
