24	TEST_CASE("narrow QEMU-virt region maps GPA 0x80010000 to file offset 0x10000")
25	{
26	  const auto path = unique_tmp_path("offset_write");
27	  constexpr std::size_t kSize = 8 * 1024 * 1024;
28	  constexpr uint64_t kBaseGpa = 0x80000000;
29	
30	  MmapBacking backing(path, kSize);
31	
32	  SimpleMemory<32> mem{
33	    "mem", MemoryRegion{kBaseGpa, kBaseGpa + kSize - 1},
34	    MemoryRegion{SimpleMemory<32>::INVALID_ADDRESS,
35	                 SimpleMemory<32>::INVALID_ADDRESS},
36	    backing.span()};
37	
38	  std::array<uint8_t, 8> pattern{0xde, 0xad, 0xbe, 0xef,
39	                                  0xca, 0xfe, 0xba, 0xbe};
40	  tlm_write(mem, kBaseGpa + 0x10000, pattern);
41	
42	  const int fd = ::open(path.c_str(), O_RDONLY);
43	  REQUIRE(fd >= 0);
44	  void* p = ::mmap(nullptr, kSize, PROT_READ, MAP_SHARED, fd, 0);
45	  REQUIRE(p != MAP_FAILED);
46	  auto* file_bytes = static_cast<const uint8_t*>(p);
47	  for (std::size_t i = 0; i < pattern.size(); ++i)
48	    CHECK(file_bytes[0x10000 + i] == pattern[i]);
49	  ::munmap(p, kSize);
50	  ::close(fd);
51	  std::filesystem::remove(path);
52	}
