54	TEST_CASE("bytes pre-placed at file offset 0x10000 read back as GPA 0x80010000")
55	{
56	  const auto path = unique_tmp_path("offset_read");
57	  constexpr std::size_t kSize = 8 * 1024 * 1024;
58	  constexpr uint64_t kBaseGpa = 0x80000000;
59	
60	  MmapBacking backing(path, kSize);
61	  backing.span()[0x10000 + 0] = 0xa5;
62	  backing.span()[0x10000 + 1] = 0x5a;
63	
64	  SimpleMemory<32> mem{
65	    "mem", MemoryRegion{kBaseGpa, kBaseGpa + kSize - 1},
66	    MemoryRegion{SimpleMemory<32>::INVALID_ADDRESS,
67	                 SimpleMemory<32>::INVALID_ADDRESS},
68	    backing.span()};
69	
70	  std::array<uint8_t, 2> out{};
71	  tlm_read(mem, kBaseGpa + 0x10000, out);
72	
73	  CHECK(out[0] == 0xa5);
74	  CHECK(out[1] == 0x5a);
75	  std::filesystem::remove(path);
